import React, { useState, useEffect } from 'react';
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION: DATA SOURCE PATH
// ==========================================
// CURRENT LOCAL SETUP: Keep it as '.' to look in the same directory.
// FUTURE S3 SETUP: Change this to your bucket URL.
const DATA_BASE_URL = '.';
// ==========================================

const RiverDashboard = () => {
  // State to store fetched data
  const [forecastData, setForecastData] = useState([]);
  const [limeDetails, setLimeDetails] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // Filenames located at the DATA_BASE_URL
  const csvFileName = 'forecast_outputs.csv';
  const txtFileName = 'lime_short_sentences.txt';

  // Helper function to parse CSV text into an array of objects
  const parseCSV = (csvText) => {
    const lines = csvText.split('\n').filter(line => line.trim() !== '');
    if (lines.length < 2) return []; 

    const headers = lines[0].split(',').map(h => h.trim());
    const data = [];

    for (let i = 1; i < lines.length; i++) {
        const values = lines[i].split(',');
        if (values.length === headers.length) {
            let rowObject = {};
            for (let j = 0; j < headers.length; j++) {
                rowObject[headers[j]] = values[j].trim();
            }
            data.push(rowObject);
        }
    }
    return data;
  };

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        // 1. Fetch and Parse CSV Forecast Data
        const csvResponse = await fetch(`${DATA_BASE_URL}/${csvFileName}`);
        if (!csvResponse.ok) throw new Error(`Failed to fetch CSV file (${csvResponse.status})`);
        const csvText = await csvResponse.text();
        const parsedForecast = parseCSV(csvText);
        setForecastData(parsedForecast);

        // 2. Fetch and Parse LIME Text Data
        const txtResponse = await fetch(`${DATA_BASE_URL}/${txtFileName}`);
        if (!txtResponse.ok) throw new Error(`Failed to fetch LIME text file (${txtResponse.status})`);
        const txtText = await txtResponse.text();
        const parsedLime = txtText.split('\n').filter(line => line.trim() !== '');
        setLimeDetails(parsedLime);

      } catch (err) {
        console.error("Error loading data:", err);
        setError("Failed to load river data. Please ensure the data files are accessible.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  if (isLoading) {
      return <div className="dashboard-loading">Loading Periyar River Data...</div>;
  }

  if (error) {
      return <div className="dashboard-error">{error}</div>;
  }

  const tableHeaders = forecastData.length > 0 ? Object.keys(forecastData[0]) : [];

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h1>Periyar River Monitoring System</h1>
        <p className="last-updated">Dashboard Last Updated: 8/08/24</p>
      </header>

      <div className="dashboard-grid">
        {/* --- Card 1: Current Water Level Status (UPDATED) --- */}
        <div className="card current-level-card">
          <h2>Current Water Level Status</h2>
          <div className="level-display-container">
              {/* Replaced Image with Text Values as requested */}
              <div className="level-date">
                  <span className="label">Date:</span> 8/08/24
              </div>
              <div className="level-value-box">
                  <span className="value">1.41</span>
                  <span className="unit">m</span>
              </div>
              <div className="level-status-indicator">
                  Status: Normal
              </div>
          </div>
        </div>

        {/* --- Card 2: 6-Hour Forecast Table --- */}
        <div className="card table-card">
          <h2>6-Hour Forecast Data</h2>
          {forecastData.length > 0 ? (
            <div className="table-responsive">
                <table className="forecast-table">
                <thead>
                    <tr>
                    {tableHeaders.map((header, index) => (
                        <th key={index}>{header.replace(/_/g, ' ')}</th>
                    ))}
                    </tr>
                </thead>
                <tbody>
                    {forecastData.map((row, rowIndex) => (
                    <tr key={rowIndex}>
                        {tableHeaders.map((header, colIndex) => (
                        <td key={colIndex}>{row[header]}</td>
                        ))}
                    </tr>
                    ))}
                </tbody>
                </table>
            </div>
          ) : (
             <p>No forecast data available.</p>
          )}
        </div>

        {/* --- Card 3: LIME Short Details --- */}
        <div className="card lime-card">
          <h2>LIME Analysis Details</h2>
          {limeDetails.length > 0 ? (
            <ul className="lime-list">
                {limeDetails.map((detail, index) => (
                    <li key={index}>{detail}</li>
                ))}
            </ul>
          ) : (
              <p>No LIME details available.</p>
          )}
        </div>
      </div>

      <footer className="dashboard-footer">
        <p>© 2023 Periyar River Monitoring Authority. All rights reserved.</p>
      </footer>
    </div>
  );
};

export default RiverDashboard;
